pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 newMin) internal {
        try c.Initialized() {} catch { return; }
        uint256 minBefore;
        try c.MinSum() returns (uint256 __r) { minBefore = __r; } catch { return; }
        bool reverted1;
        try c.SetMinSum(newMin) {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }
        try c.Initialized() {} catch { return; }
        uint256 minAfter;
        try c.MinSum() returns (uint256 __r) { minAfter = __r; } catch { return; }
        bool reverted2;
        try c.SetMinSum(newMin) {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }
        assertTrue(reverted1 && reverted2 && minAfter == minBefore);
    }

    function testFuzz_run(uint256 newMin) public {
        _run(newMin);
    }

    receive() external payable {}
}
